import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.B3IQijK_.js";const u=JSON.parse(`{"title":"Review and Improve","description":"Compare a Trading Office strategy's backtest expectation with its paper journal, then keep, pause, retire, or improve it.","frontmatter":{"title":"Review and Improve","description":"Compare a Trading Office strategy's backtest expectation with its paper journal, then keep, pause, retire, or improve it.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/review"}]]},"headers":[],"relativePath":"trading-office/review.md","filePath":"trading-office/review.md"}`),n={name:"trading-office/review.md"};function o(s,e,d,h,p,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="review-and-improve" tabindex="-1">Review and Improve <a class="header-anchor" href="#review-and-improve" aria-label="Permalink to &quot;Review and Improve&quot;">​</a></h1><p>A backtest is not the end of the strategy lifecycle. Review connects the frozen version, its original evidence, later history, and version-tagged paper trades to one explicit decision.</p><p>The Strategy Library keeps snapshots, computed journals, forward checks, employee-attributed reviews, review history, and Keep, Pause, Retire, or Improve outcomes together.</p><h2 id="open-a-strategy-s-evidence" tabindex="-1">Open a strategy&#39;s evidence <a class="header-anchor" href="#open-a-strategy-s-evidence" aria-label="Permalink to &quot;Open a strategy&#39;s evidence&quot;">​</a></h2><p>From a Trading Office pane, run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/strategies</span></span></code></pre></div><p>Select the exact version you want to review. Its Library entry keeps the version number, lifecycle status, verdict, and latest deployment state visible.</p><p>The available evidence views are:</p><table tabindex="0"><thead><tr><th>Action</th><th>What it shows or does</th></tr></thead><tbody><tr><td><strong>Snapshot</strong></td><td>Frozen hypothesis, parameters, exits, universe, fingerprint, evidence job, lineage, and deployments</td></tr><tr><td><strong>Journal</strong></td><td>Version-tagged trades, open and closed counts, wins and losses, and realized P&amp;L</td></tr><tr><td><strong>Forward check</strong></td><td>The unchanged rules over history that arrived after promotion</td></tr><tr><td><strong>Review</strong></td><td>Backtest expectation beside the paper journal, followed by a recorded decision</td></tr><tr><td><strong>Reviews</strong></td><td>Earlier outcomes, hypotheses, paper summaries, and child-version links</td></tr></tbody></table><p>These are version-specific views. Similar strategy names do not merge their evidence.</p><h2 id="read-the-paper-journal" tabindex="-1">Read the paper journal <a class="header-anchor" href="#read-the-paper-journal" aria-label="Permalink to &quot;Read the paper journal&quot;">​</a></h2><p>Choose <strong>Journal</strong> to inspect the paper transactions tagged with this strategy version. The summary is computed from Office records rather than reconstructed from conversation and includes:</p><ul><li>total, open, and closed trades;</li><li>wins and losses;</li><li>realized P&amp;L; and</li><li>each trade&#39;s entry quantity, exits, remaining quantity, and realized result.</li></ul><p>If no tagged trades exist, the journal says so. For an approved deployment, <strong>Library → Trade</strong> can create a risk-sized paper ticket that carries the strategy version and deployment IDs into the ledger.</p><h2 id="run-a-forward-check" tabindex="-1">Run a forward check <a class="header-anchor" href="#run-a-forward-check" aria-label="Permalink to &quot;Run a forward check&quot;">​</a></h2><p>A forward check re-runs the version&#39;s frozen parameters on the post-promotion date range. It is a one-cell experiment with no parameter sweep and no validation split, and it uses the normal plan → confirm → persisted run path.</p><p>Forward checks are available when the version has explicit symbols and enough post-promotion history. A scan-defined universe currently needs explicit symbols before this check can run.</p><p>Use a forward check to ask, “Did the unchanged rules continue to behave as expected?” Do not tune the frozen version from this result. A proposed change belongs in a child hypothesis.</p><h2 id="record-the-review" tabindex="-1">Record the review <a class="header-anchor" href="#record-the-review" aria-label="Permalink to &quot;Record the review&quot;">​</a></h2><p>Choose <strong>Review</strong>. tradecli displays two sides of the comparison:</p><ul><li><strong>Expectation</strong> — the stored machine verdict and available validation evidence from the original experiment.</li><li><strong>Paper</strong> — the current version journal summary.</li></ul><p>The review warns when there are fewer than ten closed paper trades. You can still record an outcome, but the evidence should be treated conservatively.</p><p>Then choose one result:</p><table tabindex="0"><thead><tr><th>Outcome</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Keep</strong></td><td>Preserve the evidence and continue with the version as-is</td></tr><tr><td><strong>Pause</strong></td><td>Stop new entries for an applicable deployment; requires a deployment that can be acted on</td></tr><tr><td><strong>Retire</strong></td><td>Permanently stop the version and applicable deployment</td></tr><tr><td><strong>Improve</strong></td><td>Create a child draft around one typed change hypothesis</td></tr></tbody></table><p>The decision is applied and recorded by the Office. AI does not choose the outcome for you.</p><h2 id="improve-without-rewriting-history" tabindex="-1">Improve without rewriting history <a class="header-anchor" href="#improve-without-rewriting-history" aria-label="Permalink to &quot;Improve without rewriting history&quot;">​</a></h2><p>For <strong>Improve</strong>, enter one change hypothesis, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stops may be too tight in high-volatility regimes; test an ATR-based stop while keeping entry rules unchanged.</span></span></code></pre></div><p>The Office clones a child draft linked to the reviewed parent. The parent keeps its original implementation, evidence, paper results, and review. The child must return to Strategy Lab, earn a new machine verdict, and be promoted independently.</p><p>This is the central discipline of the review loop: append evidence and create lineage instead of silently tuning a validated strategy.</p><h2 id="review-at-useful-moments" tabindex="-1">Review at useful moments <a class="header-anchor" href="#review-at-useful-moments" aria-label="Permalink to &quot;Review at useful moments&quot;">​</a></h2><p>Review when there is enough paper evidence to compare with the original expectation, after a material regime change, or when a forward check contradicts the backtest. If the paper sample is still thin, record that uncertainty rather than forcing a strong conclusion.</p><p>Use <strong>Reviews</strong> to inspect the decision history before starting another experiment. It shows past outcomes and the child version created by an improvement, keeping repeated debates from losing their context.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>See the full lifecycle in one tutorial → <a href="./quickstart">Your First Strategy</a></li><li>Turn the next change into a clean hypothesis → <a href="./ideas">Research and Ideas</a></li><li>Re-test a child version → <a href="./strategy-lab">Test in Strategy Lab</a></li><li>Understand strategy lineage → <a href="./concepts">Concepts and Terminology</a></li></ul>',35)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
